examples.template:
Column {
    MonarchText(text = MonarchInlineCodeStyle.markdown({{lines.0}}))
    MonarchText(
        text = MonarchInlineCodeStyle.markdown({{lines.1}}),
        style = MonarchTextStyle.Caption,
        color = MonarchTheme.colors.textMuted,
    )
}

examples.code:
Column {
    MonarchText(text = MonarchInlineCodeStyle.markdown("Set `timeout` to a number of seconds, then run `npm run sync`."))
    MonarchText(
        text = MonarchInlineCodeStyle.markdown("The file is saved to `exports/2026/report.csv`."),
        style = MonarchTextStyle.Caption,
        color = MonarchTheme.colors.textMuted,
    )
}

MonarchText(
    text = buildAnnotatedString {
        append("Exit code ")
        append(exitCode)
    },
    style = MonarchTextStyle.Caption,
)
